package vn.gastroai.be.infrastructure.security; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import vn.gastroai.be.domain.auth.Patient; import vn.gastroai.be.infrastructure.persistence.postgres.*; import java.io.IOException; import java.util.*; @Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final PatientRepository patients; private final RevokedTokenRepository revoked; public JwtAuthenticationFilter(JwtService j,PatientRepository p,RevokedTokenRepository r){jwt=j;patients=p;revoked=r;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{Claims c=jwt.parse(h.substring(7)); Long id=Long.valueOf(c.getSubject()); Optional<Patient> p=patients.findById(id); if(p.isPresent()&&!revoked.existsById(c.getId())&&p.get().getTokenVersion()==((Number)c.get("version")).intValue()){var a=new UsernamePasswordAuthenticationToken(id,null,List.of(new SimpleGrantedAuthority("ROLE_"+p.get().getRole().name()))); SecurityContextHolder.getContext().setAuthentication(a);}}catch(Exception ignored){}} chain.doFilter(req,res);} }
